import {today,monthOf,uid,types,subcategories,defaults,round,sum,shiftMonth,ratio,splitAmount,metrics,settlement,goalProgress,budgetFor,budgetTotal,carry,nextOccurrence,validData,demo,isCharge,incomeBasis} from './core.mjs';
const KEY='notre-budget-a-deux-v1';
let storageError=false;
function loadData(){try{const v=localStorage.getItem(KEY);return v?validData(JSON.parse(v)):defaults();}catch{storageError=true;return defaults();}}
let state=loadData(),isDemo=false,page='dashboard',month=monthOf(today()),personal='p1',savingScope='shared',filters={partner:'',category:'',type:'',search:'',status:''},toastTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=p=>state.profile[p]||`Partenaire ${p==='p1'?'1':'2'}`;
const unit=()=>state.profile.currency==='XOF'?'FCFA':state.profile.currency;
const num=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:['XOF','XAF'].includes(state.profile.currency)?0:2}).format(Number(n)||0);
const money=n=>`${num(n)} ${unit()}`;
const pct=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(n||0)+' %';
const monthLabel=m=>new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-01T12:00:00Z'));
const dateLabel=d=>new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const fullDate=d=>new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const modeLabel={mixed:'Finances mixtes',separate:'Finances séparées',joint:'Finances communes'};
const methods={equal:'À parts égales · 50 / 50',proportional:'Au prorata des revenus',custom:'Répartition personnalisée'};
const frequency={once:'Ponctuel',monthly:'Mensuel',variable:'Variable'};
const scopeName=p=>p==='shared'?'Commun':name(p);
const accountName=p=>p==='common'?'Compte commun':name(p);
const path={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',income:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',wallet:'M20 8V5H4a2 2 0 0 0 0 4h16v11H4a2 2 0 0 1-2-2V7m18 6h-5v4h5',card:'M3 5h18v14H3zM3 10h18m-13 5h3',split:'M12 3v6m0 0-7 7m7-7 7 7M2 13v6h6m8 0h6v-6',chart:'M3 3v18h18M7 14v3m5-8v8m5-12v12',pig:'M19 7h3v7h-3l-2 4h-2v3h-3v-3H8v3H5v-4a7 7 0 0 1 0-10l2-4 4 2h4a6 6 0 0 1 4 2M2 10H0m15-1h.01M9 7h4',target:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4',calendar:'M4 5h16v16H4zM4 10h16M8 2v6m8-6v6M8 14h2m4 0h2m-8 3h2',sliders:'M4 3v7m0 4v7m8-18v12m0 4v2m8-18v3m0 4v11M1 10h6m2 5h6m2-9h6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',file:'M14 2H4v20h16V8zm0 0v6h6M8 12h8m-8 4h8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l1-2h4l1 2 3 2 2 1 2 3-1 3 1 3-2 3-3 1-2 2h-4l-2-2-3-1-2-3 1-3-1-3 2-3 2-1z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4m-4 5v2',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',edit:'m15 3 6 6L9 21H3v-6zm-2 2 6 6',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',home:'m3 10 9-8 9 8M5 9v12h14V9m-10 12v-8h6v8',leaf:'M20 3c-13-2-18 7-14 12s15 3 14-12ZM4 21l11-11',menu:'M4 6h16M4 12h16M4 18h16',heart:'M20 4a5 5 0 0 0-8 2 5 5 0 0 0-8-2c-5 5 2 12 8 16 6-4 13-11 8-16',info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 8v7m0-11v1',refresh:'M20 7a9 9 0 1 0 1 9M20 2v6h-6',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3zm9 2v17',bell:'M5 17V9a7 7 0 0 1 14 0v8l2 2H3zm5 5h4',logout:'M9 3H3v18h6m5-5 5-4-5-4m-6 4h12',plane:'m2 16 9-4-6-6 2-2 9 5 5-2 1 2-5 5 1 7-2 1-4-6-8 2z'};
function icon(n,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path[n]||path.wallet}"/></svg>`;}
const btn=(label,action,ico='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${ico?icon(ico,15):''}${label}</button>`;
const empty=(title,desc,action,label,ico='wallet')=>`<div class="empty"><div class="empty-icon">${icon(ico,22)}</div><strong>${title}</strong><p>${desc}</p>${action?btn(label,action,'plus','small'):''}</div>`;
const selectOptions=(items,value)=>Object.entries(items).map(([v,l])=>`<option value="${esc(v)}" ${v===String(value)?'selected':''}>${esc(l)}</option>`).join('');
function field(label,input,help=''){return `<div><label>${label}</label>${input}${help?`<p class="help">${help}</p>`:''}</div>`;}
const input=(n,v='',type='text',extra='')=>`<input name="${n}" value="${esc(v)}" type="${type}" ${extra}>`;
const select=(n,items,v='',extra='')=>`<select name="${n}" ${extra}>${selectOptions(items,v)}</select>`;
function save(message='Modifications enregistrées.'){if(!isDemo){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;}catch{storageError=true;toast('Sauvegarde impossible : exportez vos données avant de fermer.');render();return;}}if(message)toast(isDemo?'Démonstration : modification temporaire.':message);render();}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200);}
const pages=[['dashboard','Tableau de bord','grid'],['profile','Notre profil','users'],['income','Nos revenus','income'],['shared','Dépenses communes','wallet'],['personal','Dépenses personnelles','card'],['split','Répartition des charges','split'],['budget','Notre budget','chart'],['savings','Notre épargne','pig'],['projects','Nos projets','target'],['calendar','Calendrier','calendar'],['simulator','Simulateur','sliders'],['analysis','Analyses','spark'],['reports','Rapports','file'],['settings','Paramètres','settings']];
function render(){document.documentElement.classList.toggle('dark-theme',state.theme==='dark');document.title='Notre Budget à Deux — Finances, Projets & Épargne';const title=pages.find(p=>p[0]===page)?.[1]||'';
document.querySelector('#app').innerHTML=`${isDemo?'<div class="demo-banner">Données fictives · Démonstration indépendante de vos finances.<button data-action="exit-demo">Revenir à mes données</button></div>':''}<aside class="sidebar"><div class="brand"><div class="brand-mark" aria-label="E et E">E&amp;E</div><div><div class="brand-name">Notre Budget à Deux</div><div class="brand-sub">Finances, Projets & Épargne</div></div></div><nav class="nav" aria-label="Navigation principale">${pages.map(([id,label,ico],i)=>`${[0,6,11].includes(i)?`<div class="nav-label">${i===0?'NOTRE QUOTIDIEN':i===6?'CONSTRUIRE ENSEMBLE':'PRENDRE DU RECUL'}</div>`:''}<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico,17)}${label}</button>`).join('')}</nav><div class="sidebar-foot"><div class="flex" style="margin-bottom:12px"><div class="avatars">${avatar('p1')}${avatar('p2','blue')}</div><div><div style="font-size:11px;color:#e3eae6">${state.profile.p1||state.profile.p2?esc(name('p1')+' & '+name('p2')):'Votre équipe, vos projets'}</div><div style="font-size:9px;margin-top:3px">${modeLabel[state.profile.mode]}</div></div></div><div class="local-info flex">${icon('lock',13)}<span>Enregistré sur cet appareil<br>Aucune synchronisation entre partenaires</span></div></div></aside><div class="shell"><header class="topbar"><div class="flex"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Ouvrir le menu">${icon('menu')}</button><div class="breadcrumb"><span>Notre espace</span>${icon('chevron',12)}<b>${title}</b></div></div><div class="top-tools"><span class="status-local"><i class="dot"></i>${storageError?'Sauvegarde à vérifier':isDemo?'Mode démonstration':'Sauvegarde locale'}</span><button class="text-btn" data-action="${isDemo?'exit-demo':'demo'}">${isDemo?'Quitter la démo':'Explorer la démo'}</button><span class="top-divider"></span><button class="icon-btn" data-action="theme" aria-label="${state.theme==='light'?'Activer le thème sombre':'Activer le thème clair'}">${icon(state.theme==='light'?'moon':'sun',18)}</button><button class="avatars" data-nav="profile" aria-label="Notre profil">${avatar('p1')}${avatar('p2','blue')}</button></div></header><main class="main">${storageError?'<div class="notice amber">Le stockage du navigateur est indisponible ou la sauvegarde est illisible. Les nouvelles saisies restent en mémoire ; exportez une sauvegarde dans Paramètres.</div>':''}${renderPage()}<footer class="footer"><span>Notre Budget à Deux — Finances, Projets & Épargne</span><span>Un pas à la fois, ensemble. ${icon('heart',10)}</span></footer></main></div>`;
 document.querySelectorAll('label').forEach((l,i)=>{if(!l.getAttribute('for')&&!l.querySelector('input')){const el=l.nextElementSibling;if(el?.matches('input,select,textarea')){el.id ||= `field-${i}`;l.htmlFor=el.id;}}});
}
function avatar(p,cls=''){return `<span class="avatar ${cls}" title="${esc(name(p))}">${esc((state.profile[p]||('P'+p.slice(1))).slice(0,2).toUpperCase())}</span>`;}
function monthPicker(){return `<div class="month-picker"><button class="icon-btn" data-action="prev-month" aria-label="Mois précédent"><span style="transform:rotate(180deg);display:flex">${icon('chevron',13)}</span></button><input type="month" id="month-select" value="${month}" min="1900-01" max="2200-12" aria-label="Mois affiché"><button class="icon-btn" data-action="next-month" aria-label="Mois suivant">${icon('chevron',13)}</button></div>`;}
function heading(title,desc,actions='',eyebrow='NOTRE ESPACE FINANCIER'){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="title-actions">${actions}</div></div>`;}
function metric(label,n,ico,note='',cls=''){return `<div class="card metric ${cls}"><div class="metric-label">${label}<span class="metric-icon ${cls==='dark'?'':ico==='wallet'?'blue':ico==='pig'?'sand':''}">${icon(ico,17)}</span></div><div class="metric-value">${num(n)}<span class="unit">${unit()}</span></div><p class="metric-note">${note}</p></div>`;}
function mini(label,n){return `<div class="mini-stat"><span>${label}</span><strong>${typeof n==='string'?n:money(n)}</strong></div>`;}
function dashboardFilter(){return `<div class="filters no-print"><span class="caption">Vue du mois</span><select id="filter-partner" aria-label="Filtrer par partenaire">${selectOptions({'':'Tout le couple',p1:name('p1'),p2:name('p2')},filters.partner)}</select><select id="filter-category" aria-label="Filtrer par catégorie">${selectOptions({'':'Toutes les catégories',...Object.fromEntries(state.categories.map(c=>[c,c]))},filters.category)}</select><select id="filter-type" aria-label="Filtrer par type">${selectOptions({'':'Tous les mouvements',...types},filters.type)}</select>${filters.partner||filters.category||filters.type?btn('Réinitialiser','clear-filters','','small'):''}<span class="caption" style="margin-left:auto">${esc(monthLabel(month))} · ${unit()}</span><p class="help" style="width:100%">Les filtres portent sur les flux et leur évolution. Les contributions et objectifs conservent leur périmètre complet.</p></div>`;}
function renderPage(){switch(page){case 'dashboard':return dashboard();case 'profile':return profilePage();case 'income':case 'shared':case 'personal':return transactionsPage();case 'split':return splitPage();case 'budget':return budgetPage();case 'savings':case 'projects':return savingsPage();case 'calendar':return calendarPage();case 'simulator':return simulatorPage();case 'analysis':return analysisPage();case 'reports':return reportsPage();case 'settings':return settingsPage();}}
function dashboard(){const v=metrics(state,month,filters),budget=budgetTotal(state,month),privacy=state.profile.share1&&state.profile.share2;return `${heading('Notre Tableau de Bord','Vos finances en un regard. Vos projets, un peu plus proches.',`${monthPicker()}${btn('Ajouter','add-transaction','plus','primary')}`,'AVANÇONS ENSEMBLE')}${!state.profile.p1&&!state.profile.p2&&!state.transactions.length?`<section class="welcome"><div><div class="eyebrow" style="font-size:8px">BIENVENUE DANS VOTRE ESPACE</div><h2>Tout commence à deux.</h2><p>Un budget qui vous ressemble, une répartition qui vous convient et des projets à construire ensemble.</p><button class="text-btn flex" data-nav="profile">Configurer notre profil ${icon('arrow',14)}</button></div><div class="welcome-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="coin">₣</div><div class="coin two">₣</div><div class="sprout">${icon('leaf',42)}</div><div class="hero-tag">Petits pas, grands projets.</div></div></section>`:''}${dashboardFilter()}${!privacy?'<div class="notice">Les totaux personnels masqués ne sont pas affichés dans cette vue. Les indicateurs globaux susceptibles de les révéler sont également masqués.</div>':''}<section class="grid cols4">${metric('Revenus du couple',v.income,'income','Revenus enregistrés · paiements confirmés')}${metric('Dépenses communes',v.shared,'wallet','Hors épargne et remboursement de capital')}${metric('Épargne commune du mois',v.sharedSaving,'pig','Versements confirmés · hors solde initial')}${privacy?metric('Solde disponible',v.available,'chart','Après dépenses, capital et épargne','dark'):'<div class="card metric dark"><div class="metric-label">Solde disponible '+icon('lock',17)+'</div><div class="metric-value">Masqué</div><p class="metric-note">Respect du partage des totaux personnels</p></div>'}</section><section class="dashboard-secondary">${mini('Dépenses personnelles',privacy?v.personal:'Masqué')}${mini('Dépenses totales du foyer',privacy?v.expense:'Masqué')}${mini('Épargne individuelle du mois',privacy?v.personalSaving:'Masqué')}${mini('Budget restant',privacy?(budget?budget-v.expense-v.principal:'À définir'):'Masqué')}${mini('Taux d’épargne global',privacy?pct(v.rate):'Masqué')}</section><div class="dashboard-charts"><section class="card"><div class="card-head"><div><h2>L’équilibre de notre mois</h2><p class="help">Revenus, dépenses et versements d’épargne</p></div><div class="legend"><span><i></i>Revenus</span><span><i style="background:#a184db"></i>Dépenses</span><span><i style="background:#78b1e8"></i>Épargne</span></div></div>${privacy?barChart():empty('Une vue confidentielle','Activez le partage des totaux pour afficher ce graphique.',null,null,'lock')}</section><section class="card"><div class="card-head"><h2>Où va notre budget ?</h2><span class="badge">${esc(monthLabel(month).split(' ')[0])}</span></div>${donutChart(v)}</section></div><div class="bottom-grid"><section class="card"><div class="card-head"><div><h2>Nos derniers mouvements</h2><p class="help">Un quotidien organisé, sans oublier l’essentiel.</p></div><button class="text-btn" data-nav="shared">Tout voir ${icon('arrow',12)}</button></div>${transactionTable(visibleTransactions(v.chosen).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),true)}</section><section class="card"><div class="card-head"><h2>Nos projets prennent vie</h2><button class="text-btn" data-nav="projects">${icon('arrow',16)}</button></div>${goalRows(state.goals.filter(g=>g.scope==='shared').slice(0,2))}<div class="insight">${icon('leaf',18)}<div><h3>Chaque pas compte.</h3><p>${state.goals.length?'Des versements réguliers vous aident à avancer à votre rythme.':'Définissez un premier objectif et choisissez un rythme qui vous convient.'}</p></div></div></section></div><div class="grid cols2" style="margin-top:20px"><section class="card"><div class="card-head"><h2>Revenus et contributions</h2><button class="text-btn" data-nav="split">Détail ${icon('arrow',12)}</button></div>${partnerChart()}</section><section class="card"><div class="card-head"><h2>Évolution des dépenses</h2><span class="caption">6 mois</span></div>${privacy?lineChart():empty('Totaux masqués','Le partage des deux totaux est nécessaire.',null,null,'lock')}</section><section class="card"><div class="card-head"><h2>Notre équilibre personnel et commun</h2></div>${privacy?spendingBreakdown(v):empty('Totaux masqués','Paramétrez le partage dans Notre profil.',null,null,'lock')}</section><section class="card"><div class="card-head"><h2>Prochaines échéances</h2><button class="text-btn" data-nav="calendar">Calendrier ${icon('arrow',12)}</button></div>${upcoming()}</section></div><p class="formula">Solde disponible = revenus encaissés − dépenses payées − capital remboursé − versements d’épargne. Les transferts internes et remboursements entre partenaires ne modifient pas le solde global. Les soldes d’épargne initiaux constituent un stock distinct des versements du mois.</p>`;}
const colors=['#4f6de0','#a184db','#92b8ee','#b8a5e8','#b3c7f2','#a18bc4','#96a8dc'];
function chartFilter(){return {partner:filters.partner,category:filters.category,type:filters.type};}
function barChart(){const months=Array.from({length:6},(_,i)=>shiftMonth(month,i-5)),data=months.map(m=>metrics(state,m,chartFilter())),max=Math.max(1,...data.flatMap(v=>[v.income,v.expense,v.saved]));const H=155,W=590;return `<svg class="chart" viewBox="0 0 640 220" role="img" aria-label="Revenus, dépenses et épargne des six derniers mois">${[0,1,2,3].map(i=>`<line class="grid-line" x1="46" y1="${15+i*H/3}" x2="630" y2="${15+i*H/3}"/><text x="39" y="${19+i*H/3}" text-anchor="end">${num(max*(1-i/3)/1000)} k</text>`).join('')}${data.map((v,i)=>{const x=66+i*W/6;return [v.income,v.expense,v.saved].map((n,j)=>`<rect x="${x+j*18}" y="${170-n/max*H}" width="12" height="${n/max*H}" rx="3" fill="${['#4f6de0','#a184db','#78b1e8'][j]}"><title>${esc(monthLabel(months[i]))} · ${['Revenus','Dépenses','Épargne'][j]} : ${money(n)}</title></rect>`).join('')+`<text x="${x+24}" y="198" text-anchor="middle">${esc(new Intl.DateTimeFormat('fr-FR',{month:'short'}).format(new Date(months[i]+'-15')))}</text>`;}).join('')}${max===1?'<text x="340" y="90" text-anchor="middle">Vos premiers mouvements donneront vie à ce graphique.</text>':''}</svg>`;}
function donutChart(v){let items=state.categories.map(c=>({name:c,value:sum(v.paid.filter(t=>['expense','interest'].includes(t.type)&&t.category===c&&(t.scope==='shared'||state.profile['share'+t.scope.slice(1)])))})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);if(items.length>5)items=[...items.slice(0,4),{name:'Autres catégories',value:sum(items.slice(4),x=>x.value)}];const total=sum(items,x=>x.value);let offset=0;const circles=items.map((x,i)=>{const length=x.value/total*289,at=offset;offset+=length;return `<circle cx="60" cy="60" r="46" fill="none" stroke="${colors[i]}" stroke-width="12" stroke-dasharray="${Math.max(0,length-2)} ${289-Math.max(0,length-2)}" stroke-dashoffset="${-at}"><title>${esc(x.name)} : ${money(x.value)} (${pct(x.value/total*100)})</title></circle>`;}).join('');return `<div class="donut-wrap"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="Répartition des dépenses par catégorie"><circle cx="60" cy="60" r="46" fill="none" stroke="var(--line)" stroke-width="12"/>${circles}</svg><div class="donut-label"><small>${total?'TOTAL VISIBLE':'À VOTRE RYTHME'}</small><strong>${num(total)}</strong><small>${unit()}</small></div></div><div class="donut-legend">${items.length?items.map((x,i)=>`<button data-action="category-filter" data-category="${esc(x.name)}"><i class="dot" style="color:${colors[i]}"></i>${esc(x.name)}<b>${pct(x.value/total*100)}</b></button>`).join(''):'<span>Aucune dépense enregistrée</span><span class="muted">Votre répartition apparaîtra ici.</span>'}</div></div><p class="help" style="text-align:center;margin-top:18px">${total?'Sélectionnez une catégorie pour filtrer la vue.':'Commencez par ajouter votre première dépense.'}</p>`;}
function partnerChart(){const [a,b]=incomeBasis(state,month),s=settlement(state,month),max=Math.max(1,a,b,...s.actual);return `<div class="legend" style="margin-bottom:22px"><span><i></i>Revenus</span><span><i style="background:#a184db"></i>Charges payées individuellement</span></div><div class="comparison">${['p1','p2'].map((p,i)=>`<div class="comparison-row"><span>${esc(name(p))}</span><div class="compare-bars"><div><span style="width:${[a,b][i]/max*100}%"></span></div><div class="actual"><span style="width:${s.actual[i]/max*100}%"></span></div></div><span style="text-align:right">${money([a,b][i])}<br><span class="muted">${money(s.actual[i])}</span></span></div>`).join('')}</div><p class="help" style="margin-top:20px">Chaque contribution compte. Les montants reflètent vos accords, sans classement entre partenaires.</p>`;}
function lineChart(){const ms=Array.from({length:6},(_,i)=>shiftMonth(month,i-5)),vs=ms.map(m=>metrics(state,m,chartFilter()).expense),max=Math.max(1,...vs),coords=vs.map((v,i)=>[50+i*108,165-v/max*135]);return `<svg class="chart" viewBox="0 0 640 220" role="img" aria-label="Évolution mensuelle des dépenses">${[30,75,120,165].map(y=>`<line x1="42" x2="620" y1="${y}" y2="${y}" class="grid-line"/>`).join('')}<path d="M${coords.map(x=>x.join(',')).join(' L')} L590 165 L50 165Z" fill="#4f6de010"/><path d="M${coords.map(x=>x.join(',')).join(' L')}" fill="none" stroke="#4f6de0" stroke-width="2.5"/>${coords.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#4f6de0"><title>${esc(monthLabel(ms[i]))} : ${money(vs[i])}</title></circle><text x="${x}" y="195" text-anchor="middle">${esc(new Intl.DateTimeFormat('fr-FR',{month:'short'}).format(new Date(ms[i]+'-15')))}</text>`).join('')}${max===1?'<text x="320" y="100" text-anchor="middle">Votre historique se construira au fil des mois.</text>':''}</svg>`;}
function spendingBreakdown(v){const vals=[v.shared,sum(v.paid.filter(t=>['expense','interest'].includes(t.type)&&t.scope==='p1')),sum(v.paid.filter(t=>['expense','interest'].includes(t.type)&&t.scope==='p2'))],total=sum(vals,x=>x);return `<div class="split-bar" style="height:16px;margin:26px 0 22px">${vals.map((v,i)=>`<span style="width:${total?v/total*100:0}%;background:${colors[i]}"><title>${money(v)}</title></span>`).join('')}</div><div class="grid cols3">${['Commun',name('p1'),name('p2')].map((p,i)=>`<div><span class="caption flex"><i class="dot" style="color:${colors[i]}"></i>${esc(p)}</span><h3 style="margin:9px 0 5px">${money(vals[i])}</h3><span class="caption">${pct(total?vals[i]/total*100:0)}</span></div>`).join('')}</div>`;}
function visibleTransactions(txs){return txs.filter(t=>t.scope==='shared'||state.profile['details'+t.scope.slice(1)]||t.type==='income');}
function transactionTable(txs,compact=false){if(!txs.length)return empty('Votre histoire financière commence ici.','Ajoutez un revenu, une dépense ou un versement pour suivre vos premiers mouvements.','add-transaction','Ajouter un mouvement');return `<div class="table-wrap"><table><thead><tr><th>Mouvement</th><th>Date</th><th>${compact?'Espace':'Partenaire / compte'}</th>${compact?'':'<th>Catégorie</th><th>Statut</th>'}<th style="text-align:right">Montant</th><th><span class="hide">Actions</span></th></tr></thead><tbody>${txs.map(t=>`<tr><td><div class="flex"><span class="transaction-icon">${icon(t.type==='income'?'income':t.type==='saving'?'pig':['transfer','reimbursement'].includes(t.type)?'split':'wallet',15)}</span><div><div class="desc">${esc(t.description||t.source||t.subcategory||types[t.type])}</div><div class="sub">${types[t.type]}${t.frequency==='monthly'?' · Mensuel':''}</div></div></div></td><td>${esc(dateLabel(t.date))}</td><td><span class="badge ${t.scope==='p2'?'blue':''}">${esc(compact?scopeName(t.scope):t.type==='income'||t.type==='saving'?name(t.owner):['transfer','reimbursement'].includes(t.type)?accountName(t.from)+' → '+accountName(t.to):accountName(t.payer))}</span></td>${compact?'':`<td>${esc(t.category)}${t.subcategory?`<div class="sub">${esc(t.subcategory)}</div>`:''}</td><td><span class="badge ${t.status==='planned'?'amber':''}">${t.status==='planned'?'Prévu':'Confirmé'}</span></td>`}<td class="amount-cell ${t.type==='income'?'positive':''}">${t.type==='income'?'+ ':''}${money(t.amount)}</td><td><div class="flex" style="gap:1px"><button class="icon-btn" data-action="edit-transaction" data-id="${esc(t.id)}" aria-label="Modifier ${esc(t.description||types[t.type])}">${icon('edit',14)}</button>${compact?'':`<button class="icon-btn negative" data-action="delete-transaction" data-id="${esc(t.id)}" aria-label="Supprimer le mouvement">${icon('trash',14)}</button>`}</div></td></tr>`).join('')}</tbody></table></div>`;}
function transactionFilters(){return `<div class="filters"><input id="transaction-search" placeholder="Rechercher une description, un justificatif…" value="${esc(filters.search)}" aria-label="Rechercher dans les mouvements"><select id="filter-category" aria-label="Catégorie">${selectOptions({'':'Toutes les catégories',...Object.fromEntries(state.categories.map(c=>[c,c]))},filters.category)}</select><select id="filter-partner" aria-label="Partenaire">${selectOptions({'':'Tous les partenaires',p1:name('p1'),p2:name('p2'),common:'Compte commun'},filters.partner)}</select><select id="filter-status" aria-label="Statut">${selectOptions({'':'Tous les statuts',paid:'Confirmé',planned:'Prévu'},filters.status)}</select><select id="filter-type" aria-label="Type de mouvement">${selectOptions({'':'Tous les types',...types},filters.type)}</select>${btn('Effacer','clear-filters','','small')}</div>`;}
function filteredTransactions(){return state.transactions.filter(t=>monthOf(t.date)===month&&(page==='income'?t.type==='income':page==='shared'?t.scope==='shared'&&t.type!=='income':t.scope===personal&&t.type!=='income')).filter(t=>(!filters.category||t.category===filters.category)&&(!filters.partner||t.owner===filters.partner||t.payer===filters.partner)&&(!filters.status||t.status===filters.status)&&(!filters.type||t.type===filters.type)&&(!filters.search||[t.description,t.source,t.receipt,t.subcategory,t.category].join(' ').toLocaleLowerCase('fr').includes(filters.search.toLocaleLowerCase('fr')))).sort((a,b)=>b.date.localeCompare(a.date));}
function transactionsPage(){const v=metrics(state,month),isIncome=page==='income',isPersonal=page==='personal',hidden=isPersonal&&!state.profile['details'+personal.slice(1)],ts=filteredTransactions(),shown=hidden?[]:visibleTransactions(ts);return `${heading(isIncome?'Nos Revenus':isPersonal?`Budget Personnel — ${esc(name(personal))}`:'Nos Dépenses Communes',isIncome?'Toutes vos sources de revenus, pour une vision commune.':isPersonal?'Un espace pour votre autonomie et vos priorités.':'Le quotidien se partage. Gardons une trace claire de nos charges.',`${monthPicker()}${btn(isIncome?'Ajouter un revenu':'Ajouter un mouvement','add-transaction','plus','primary')}`)}${isPersonal?`<div class="tabs">${['p1','p2'].map(p=>`<button class="tab ${personal===p?'active':''}" data-action="personal-tab" data-partner="${p}">${esc(name(p))}</button>`).join('')}</div><div class="notice amber">Les détails personnels sont masqués par défaut. Ce masquage est visuel : ce navigateur ne propose ni compte partenaire sécurisé ni synchronisation. Chaque personne utilisant cet appareil peut modifier ces réglages.</div>`:''}<div class="grid cols3" style="margin-bottom:22px">${isIncome?metric('Revenus de '+esc(name('p1')),incomeBasis(state,month)[0],'income','Montants effectivement enregistrés')+metric('Revenus de '+esc(name('p2')),incomeBasis(state,month)[1],'income','Montants effectivement enregistrés')+metric('Revenus cumulés',v.income,'chart',`Fixes : ${money(v.fixed)} · Variables : ${money(v.variable)}`):isPersonal?state.profile['share'+personal.slice(1)]?metric('Dépenses personnelles',sum(v.paid.filter(t=>['expense','interest'].includes(t.type)&&t.scope===personal)),'wallet','Hors capital et épargne')+metric('Épargne personnelle du mois',sum(v.paid.filter(t=>t.type==='saving'&&t.scope===personal)),'pig','Versements confirmés')+metric('Budget personnel',budgetFor(state,month)[personal],'chart','Plan mensuel personnel'):'<div class="card"><h2>Totaux personnels masqués</h2><p class="subtitle">Le partage de ces montants est désactivé dans Notre profil.</p></div>':metric('Dépenses communes payées',v.shared,'wallet','Hors remboursement de capital')+metric('Charges communes à venir',sum(v.chosen.filter(t=>t.scope==='shared'&&isCharge(t)&&t.status==='planned')),'calendar','Prévisions · exclues du solde disponible')+metric('Capital remboursé en commun',sum(v.paid.filter(t=>t.type==='principal'&&t.scope==='shared')),'card','Sortie de trésorerie distincte des frais')}</div>${isIncome?`<div class="card" style="margin-bottom:20px">${partnerChart()}</div>`:''}<div class="card"><div class="card-head"><h2>${isIncome?'Historique des revenus':'Historique des mouvements'}</h2><div class="flex">${btn('CSV pour Excel','export-csv','download','small')}${btn('Échéances du mois','generate-recurring','refresh','small')}</div></div>${hidden?`<div class="restricted">${icon('lock',24)}<h3>Détails personnels masqués sur cet appareil</h3><p>Affichez-les uniquement avec l’accord de ${esc(name(personal))}. Ce réglage ne constitue pas une protection par mot de passe.</p>${btn('Afficher sur cet appareil','show-personal','lock','',`data-partner="${personal}"`)}</div>`:transactionFilters()+transactionTable(shown)}<p class="help" style="margin-top:15px">${hidden?'':shown.length+' mouvement(s) affiché(s). '}${isIncome?'Les revenus mensuels du profil servent à la planification ; seuls les revenus saisis ici sont comptabilisés.':'Un remboursement entre partenaires ne crée aucune nouvelle dépense. Les transferts internes sont exclus des revenus et des dépenses.'}</p></div>`;}
function profilePage(){const p=state.profile;return `${heading('Notre Profil Financier','Deux personnes, un accord qui vous ressemble.',btn('Enregistrer le profil','submit-profile','check','primary'))}<form id="profile-form" data-form="profile"><div class="grid cols2"><section class="card"><div class="card-head"><h2>${icon('users',17)} Notre équipe</h2><span class="badge">À votre rythme</span></div><div class="grid cols2">${field('Prénom du partenaire 1',input('p1',p.p1,'text','maxlength="50" placeholder="Prénom"'))}${field('Prénom du partenaire 2',input('p2',p.p2,'text','maxlength="50" placeholder="Prénom"'))}${field(`Revenu mensuel prévu · partenaire 1 (${unit()})`,input('salary1',p.salary1||'','number','min="0" max="1000000000000" step="any" placeholder="0"'))}${field(`Revenu mensuel prévu · partenaire 2 (${unit()})`,input('salary2',p.salary2||'','number','min="0" max="1000000000000" step="any" placeholder="0"'))}${field('Devise',select('currency',{XOF:'FCFA · XOF',XAF:'FCFA · XAF',EUR:'Euro · EUR',USD:'Dollar américain · USD',CAD:'Dollar canadien · CAD',GBP:'Livre sterling · GBP',CHF:'Franc suisse · CHF',MAD:'Dirham marocain · MAD'},p.currency))}${field('Début du suivi',input('start',p.start,'date','required'))}</div><p class="help" style="margin-top:15px">Les revenus prévus ne créent pas d’encaissement. La devise est une unité d’affichage : changer de devise ne convertit pas les montants existants.</p><h3 class="section-heading">Nos priorités</h3><div class="stack">${field('Objectifs de '+esc(name('p1')),`<textarea name="goals1" maxlength="2000" placeholder="Ce qui compte pour moi…">${esc(p.goals1)}</textarea>`)}${field('Objectifs de '+esc(name('p2')),`<textarea name="goals2" maxlength="2000" placeholder="Ce qui compte pour moi…">${esc(p.goals2)}</textarea>`)}${field('Nos objectifs communs',`<textarea name="goalsShared" maxlength="2000" placeholder="Ce que nous souhaitons construire ensemble…">${esc(p.goalsShared)}</textarea>`)}</div></section><div class="stack"><section class="card"><h2>Notre mode de gestion</h2><div style="margin-top:20px">${field('Organisation financière',select('mode',{separate:'Mode A — Finances séparées',joint:'Mode B — Finances communes',mixed:'Mode C — Finances mixtes'},p.mode),'Séparées : espaces individuels et charges communes distincts. Communes : vue consolidée avec identification de chacun. Mixtes : budgets personnels et contributions au foyer. Tous les historiques restent accessibles.')}<div class="notice" style="margin-top:16px;margin-bottom:0">${p.mode==='mixed'?'Chacun garde son espace personnel et contribue aux dépenses et projets communs.':p.mode==='joint'?'Votre budget de référence est celui du foyer ; les propriétaires et payeurs restent identifiés.':'Les vues personnelles sont mises en avant, avec une répartition dédiée aux charges communes.'}</div></div><h3 class="section-heading">Notre accord de répartition</h3><div class="grid cols2">${field('Méthode par défaut',select('split',methods,p.split))}${field('Part du partenaire 1 (%)',input('percent',p.percent,'number','min="0" max="100" step="0.1"'),'Utilisée uniquement pour la méthode personnalisée.')}</div><p class="help" style="margin-top:12px">Changer l’accord s’applique aux mouvements portant « Accord du couple ». Une méthode choisie explicitement sur un mouvement reste inchangée.</p></section><section class="card"><h2>Autonomie et visibilité</h2><p class="help">Choisissez ensemble ce que l’interface affiche. Le stockage local ne garantit aucune séparation sécurisée entre utilisateurs de cet appareil.</p>${['p1','p2'].map((p,i)=>`<h3 style="margin:22px 0 10px">${esc(name(p))}</h3><label class="checkbox-row"><input type="checkbox" name="share${i+1}" ${state.profile['share'+(i+1)]?'checked':''}>Afficher mes totaux de dépenses et d’épargne dans les vues communes</label><label class="checkbox-row"><input type="checkbox" name="details${i+1}" ${state.profile['details'+(i+1)]?'checked':''}>Afficher mes transactions personnelles sur cet appareil</label>`).join('')}<div class="notice amber" style="margin-top:20px;margin-bottom:0">Pas de connexion de deux comptes, de synchronisation distante ou de notifications automatiques. Exportez vos données pour les sauvegarder ou les déplacer.</div></section></div></div><div class="form-actions"> <button class="btn primary" type="submit">${icon('check',15)} Enregistrer notre profil</button></div></form>`;}
function splitPage(){const s=settlement(state,month),r=ratio(state,month),basis=incomeBasis(state,month),max=Math.max(1,...s.expected,...s.actual);return `${heading('Répartition Équitable des Charges','Un accord clair, pour contribuer avec sérénité.',monthPicker())}<div class="grid cols2"><section class="card"><h2>Notre accord du mois</h2><p class="subtitle">${esc(methods[state.profile.split])}</p><div class="tabs" style="margin-top:22px">${Object.entries({equal:'50 / 50',proportional:'Au prorata',custom:'Personnalisée'}).map(([k,l])=>`<button class="tab ${state.profile.split===k?'active':''}" data-action="set-split" data-method="${k}">${l}</button>`).join('')}</div>${state.profile.split==='custom'?`<label for="split-range">Part de ${esc(name('p1'))} : <b>${pct(state.profile.percent)}</b></label><input type="range" id="split-range" min="0" max="100" step="1" value="${state.profile.percent}">`:''}<div class="split-bar"><span style="width:${r*100}%"></span><span style="width:${100-r*100}%"></span></div><div class="between"><span>${esc(name('p1'))} <b>${pct(r*100)}</b></span><span>${esc(name('p2'))} <b>${pct((1-r)*100)}</b></span></div><p class="help" style="margin-top:20px">Base du prorata : ${basis[0]+basis[1]?'revenus encaissés dans le mois':'revenus mensuels prévus du profil, faute d’encaissement saisi'}. Sans revenu ni prévision, le calcul utilise 50 / 50. Les différences de revenus ne reflètent pas l’engagement de chacun.</p><p class="help">Chaque charge peut utiliser une méthode indépendante. Les pourcentages ci-dessus sont ceux de l’accord par défaut.</p></section><section class="card"><div class="card-head"><h2>Régularisation du mois</h2><span class="badge">Paiements confirmés</span></div><div class="big-number ${s.amount?'':'positive'}">${money(s.amount)}</div><p>${s.amount?`de <b>${esc(name(s.from))}</b> vers <b>${esc(name(s.to))}</b>`:'Vos charges personnelles sont équilibrées selon votre accord.'}</p><p class="help" style="margin:15px 0 20px">Transfert minimal calculé sur les charges communes payées, après les remboursements déjà enregistrés.</p>${s.amount?btn('Enregistrer la régularisation','settle','check','primary'):''}<div class="notice" style="margin-top:22px;margin-bottom:0">${money(s.common)} payés par le compte commun. Ces paiements sont répartis selon la méthode de chaque charge pour le suivi, mais exclus du transfert entre partenaires. Le financement réel du compte commun se suit dans les transferts internes.</div></section></div><section class="card" style="margin-top:20px"><div class="card-head"><h2>Contributions attendues et paiements individuels</h2><div class="legend"><span><i></i>Attendu</span><span><i style="background:#a184db"></i>Payé individuellement</span></div></div><div class="comparison">${['p1','p2'].map((p,i)=>`<div class="comparison-row"><span>${esc(name(p))}</span><div class="compare-bars"><div><span style="width:${s.expected[i]/max*100}%"></span></div><div class="actual"><span style="width:${s.actual[i]/max*100}%"></span></div></div><span style="text-align:right">${money(s.expected[i])}<br><span class="muted">${money(s.actual[i])}</span></span></div>`).join('')}</div><div class="table-wrap" style="margin-top:25px"><table><thead><tr><th>Indicateur</th><th>${esc(name('p1'))}</th><th>${esc(name('p2'))}</th></tr></thead><tbody><tr><td>Contribution attendue · charges payées</td><td>${money(s.expected[0])}</td><td>${money(s.expected[1])}</td></tr><tr><td>Paiements individuels effectifs</td><td>${money(s.actual[0])}</td><td>${money(s.actual[1])}</td></tr><tr><td>Quote-part couverte par le compte commun</td><td>${money(s.commonShare[0])}</td><td>${money(s.commonShare[1])}</td></tr><tr><td>Régularisation nette restante</td><td>${s.balance>0?'À verser : ':s.balance<0?'Avance à recevoir : ':''}${money(Math.abs(s.balance))}</td><td>${s.balance<0?'À verser : ':s.balance>0?'Avance à recevoir : ':''}${money(Math.abs(s.balance))}</td></tr></tbody></table></div><p class="formula">Attendu = somme des parts calculées sur chaque charge commune confirmée. Restant du partenaire 1 = attendu − quote-part du compte commun − paiement individuel − remboursements nets versés. La part du partenaire 2 est calculée par différence pour conserver exactement le montant de la charge.</p></section>`;}
function budgetStatus(actual,limit){return !limit?{label:'À définir',color:'var(--muted)'}:actual>limit?{label:'Dépassé',color:'var(--red)'}:actual>=limit*.8?{label:'À surveiller',color:'var(--orange)'}:{label:'Dans le budget',color:'var(--success)'};}
function budgetPage(){const b=budgetFor(state,month),v=metrics(state,month),total=budgetTotal(state,month),privacy=state.profile.share1&&state.profile.share2;return `${heading('Planification de Notre Budget','Un cap mensuel souple, adapté à vos priorités.',`${monthPicker()}${btn('Copier le mois précédent','copy-budget','refresh')}`)}${!privacy?'<div class="notice">Les consommations personnelles et consolidées sont masquées selon vos réglages. Les charges communes restent visibles.</div>':''}<div class="grid cols3" style="margin-bottom:20px">${metric('Budget de décaissements',total,'wallet',`Report inclus : ${money(carry(state,month))}`)}${privacy?metric('Décaissements réalisés',v.expense+v.principal,'chart','Dépenses, frais et capital · hors épargne'):'<div class="card"><h2>Décaissements masqués</h2></div>'}${privacy?metric('Budget restant',total-v.expense-v.principal,'pig','Le budget d’épargne est suivi séparément'):'<div class="card"><h2>Reste masqué</h2></div>'}</div><form data-form="budget"><div class="grid cols2"><section class="card"><div class="card-head"><h2>Nos enveloppes mensuelles</h2><span class="caption">${esc(monthLabel(month))}</span></div><div class="grid cols2">${[['shared','Budget commun'],['p1',`Budget de ${esc(name('p1'))}`],['p2',`Budget de ${esc(name('p2'))}`],['saving','Objectif d’épargne commune']].map(([k,l])=>field(l+` (${unit()})`,input(k,b[k]||'','number','min="0" max="1000000000000" step="any" placeholder="0"'))).join('')}</div><label class="checkbox-row"><input type="checkbox" name="rollover" ${b.rollover?'checked':''}>Reporter le budget de décaissements non utilisé du mois précédent</label><p class="help">Le report s’ajoute une seule fois à l’enveloppe globale. Les sous-catégories ne sont pas ajoutées au budget commun.</p><h3 class="section-heading">Détail du budget commun</h3><div class="grid cols2">${state.categories.map(c=>field(esc(c),input('cat:'+c,b.categories[c]||'','number','min="0" max="1000000000000" step="any" placeholder="0"'))).join('')}</div><div class="form-actions"><button class="btn primary" type="submit">${icon('check',15)} Enregistrer le budget</button></div></section><div class="stack"><section class="card"><h2>Prévu et réalisé</h2>${[['shared','Charges communes'],['p1',name('p1')],['p2',name('p2')]].map(([k,l])=>{const visible=k==='shared'||state.profile['share'+k.slice(1)];const a=sum(v.paid.filter(t=>isCharge(t)&&t.scope===k)),s=budgetStatus(a,b[k]);return `<div class="budget-row"><div class="between"><h3>${esc(l)}</h3><span class="caption" style="color:${visible?s.color:'var(--muted)'}">${visible?s.label:'Masqué'}</span></div>${visible?`<div class="progress"><div style="width:${b[k]?Math.min(100,a/b[k]*100):0}%;background:${s.color}"></div></div><div class="between caption"><span>${money(a)} / ${money(b[k])}</span><span>${b[k]?pct(a/b[k]*100):'—'}</span></div>`:''}</div>`;}).join('')}${Object.entries(b.categories).filter(([,n])=>n>0).map(([c,n])=>{const a=sum(v.paid.filter(t=>isCharge(t)&&t.scope==='shared'&&t.category===c)),s=budgetStatus(a,n);return `<div class="budget-row"><div class="between"><span>${esc(c)}</span><span class="caption" style="color:${s.color}">${s.label}</span></div><div class="progress"><div style="width:${Math.min(100,a/n*100)}%;background:${s.color}"></div></div><div class="between caption"><span>${money(a)} / ${money(n)}</span><span>Reste : ${money(n-a)}</span></div></div>`;}).join('')}<div class="budget-row"><div class="between"><h3>Épargne commune</h3><span class="caption">${money(v.sharedSaving)} / ${money(b.saving)}</span></div><div class="progress"><div style="width:${b.saving?Math.min(100,v.sharedSaving/b.saving*100):0}%"></div></div></div></section><section class="card"><h2>Un repère, à adapter</h2><p class="subtitle">Le cadre 50 / 30 / 20 est facultatif. Ajustez les trois parts selon vos charges et responsabilités.</p><div class="grid cols3" style="margin-top:20px">${field('Besoins (%)',input('needs',50,'number','id="rule-needs" min="0" max="100"'))}${field('Envies (%)',input('wants',30,'number','id="rule-wants" min="0" max="100"'))}${field('Épargne (%)',input('saveRule',20,'number','id="rule-save" min="0" max="100"'))}</div><div id="rule-result" class="notice" style="margin:16px 0 0">Sur ${money(v.income)} de revenus : ${money(v.income*.5)} de besoins, ${money(v.income*.3)} d’envies et ${money(v.income*.2)} d’épargne. Aucun budget n’est remplacé.</div></section></div></div></form>`;}
function goalRows(gs){if(!gs.length)return empty('Quel sera votre premier projet ?','Un fonds de sécurité, un voyage, un chez-vous… Donnez une destination à votre épargne.','add-goal','Créer un objectif','target');return gs.map(g=>{const p=goalProgress(state,g);return `<div class="goal-row"><div class="between"><div class="flex"><span class="goal-icon">${icon(g.priority==='high'?'lock':'target',19)}</span><div><h3>${esc(g.name)}</h3><span class="caption">Objectif : ${money(g.target)}</span></div></div><span class="badge">${pct(p.percent)}</span></div><div class="progress"><div style="width:${p.percent}%"></div></div><div class="between caption"><span>${money(p.saved)} épargnés</span><span>${money(p.remaining)} restants</span></div></div>`;}).join('');}
function savingsPage(){const gs=state.goals.filter(g=>g.scope===savingScope),visible=savingScope==='shared'||state.profile['share'+savingScope.slice(1)],detail=savingScope==='shared'||state.profile['details'+savingScope.slice(1)],stock=sum(gs,g=>goalProgress(state,g).saved),monthly=sum(gs,g=>g.monthly);return `${heading(page==='projects'?'Nos Projets, Notre Avenir':savingScope==='shared'?'Notre Épargne Commune':'Mon Épargne Personnelle','Chaque objectif mérite un plan. Chaque versement vous en rapproche.',`${monthPicker()}${btn('Nouvel objectif','add-goal','plus','primary')}`)}<div class="tabs">${['shared','p1','p2'].map(p=>`<button class="tab ${savingScope===p?'active':''}" data-action="saving-tab" data-partner="${p}">${p==='shared'?'Ensemble':esc(name(p))}</button>`).join('')}</div>${savingScope!=='shared'?'<div class="notice amber">Les informations personnelles sont affichées selon vos réglages locaux. Cette application ne fournit pas de confidentialité entre deux comptes distincts.</div>':''}${visible?`<div class="grid cols3" style="margin-bottom:20px">${metric('Épargne constituée',stock,'pig','Soldes initiaux + versements confirmés, toutes dates')}${metric('Objectif mensuel',monthly,'calendar','Somme des contributions prévues')}${metric('Reste à financer',sum(gs,g=>goalProgress(state,g).remaining),'target',gs.length+' objectif(s) défini(s)')}</div>`:'<div class="notice">Les totaux d’épargne de cet espace sont masqués.</div>'}${!detail?`<div class="card restricted">${icon('lock',26)}<h3>Détail des objectifs personnels masqué</h3><p>Affichage uniquement avec l’accord de la personne concernée sur cet appareil.</p>${btn('Afficher sur cet appareil','show-personal','lock','',`data-partner="${savingScope}"`)}</div>`:gs.length?`<div class="grid cols2">${gs.map(goalCard).join('')}</div>`:`<section class="card">${empty('Vos projets commencent ici.','Créez votre objectif, sa date cible et la contribution mensuelle que vous choisissez.','add-goal','Créer mon premier objectif','target')}</section>`}`;}
function goalCard(g){const p=goalProgress(state,g),r=ratio(state,month,g.split,g.percent),monthsLeft=Math.max(0,(Number(g.deadline.slice(0,4))-Number(today().slice(0,4)))*12+Number(g.deadline.slice(5,7))-Number(today().slice(5,7))),behind=p.remaining>0&&(g.deadline<today()||p.months===null||p.months>monthsLeft),part1=round(g.monthly*r,state.profile.currency);return `<section class="card"><div class="card-head"><div class="flex"><span class="goal-icon">${icon(g.priority==='high'?'lock':'target',21)}</span><div><h2>${esc(g.name)}</h2><p class="help">${esc(scopeName(g.scope))} · Priorité ${g.priority==='high'?'haute':g.priority==='low'?'basse':'moyenne'}</p></div></div><div class="flex"><button class="icon-btn" data-action="edit-goal" data-id="${esc(g.id)}" aria-label="Modifier l’objectif">${icon('edit',15)}</button><button class="icon-btn" data-action="delete-goal" data-id="${esc(g.id)}" aria-label="Supprimer l’objectif">${icon('trash',15)}</button></div></div><div class="between"><div><h2 style="font-size:24px">${money(p.saved)}</h2><p class="help">sur ${money(g.target)}</p></div><span class="badge ${behind?'amber':''}">${pct(p.percent)}</span></div><div class="progress" style="height:8px;margin:20px 0 12px"><div style="width:${p.percent}%"></div></div><div class="between caption"><span>Reste : ${money(p.remaining)}</span><span>Cible : ${esc(fullDate(g.deadline))}</span></div><div class="grid cols2" style="margin-top:22px"><div><div class="caption">Contribution prévue / mois</div><h3 style="margin-top:7px">${money(g.monthly)}</h3></div><div><div class="caption">Réalisation estimée</div><h3 style="margin-top:7px">${!p.remaining?'Objectif atteint':p.estimated?esc(monthLabel(p.estimated)):'À définir'}</h3></div></div>${g.scope==='shared'?`<div class="notice" style="margin:20px 0 0"><b>${esc(methods[g.split])}</b><br>Prévu : ${esc(name('p1'))} ${money(part1)} · ${esc(name('p2'))} ${money(g.monthly-part1)}<br>Versé à ce jour : ${esc(name('p1'))} ${money(p.p1)} · ${esc(name('p2'))} ${money(p.p2)}. Le solde initial n’est attribué à aucun partenaire.</div>`:''}${behind?'<p class="help warning" style="margin-top:12px">À ce rythme constant, la date cible ne serait pas tenue. Vous pouvez ajuster la date ou le versement prévu.</p>':''}<p class="help" style="margin-top:12px">Estimation sans rendement, inflation ou imprévu. Le solde initial n’est pas recompté comme revenu.</p><div class="between" style="margin-top:18px">${btn('Ajouter un versement','goal-deposit','plus','small',`data-id="${esc(g.id)}"`)}${btn('Historique','goal-history','book','small',`data-id="${esc(g.id)}"`)}</div></section>`;}
function calendarItems(){const items=[];state.events.filter(e=>e.scope==='shared'||state.profile['details'+e.scope.slice(1)]).forEach(e=>{if(e.date.slice(0,7)===month)items.push({...e,eventId:e.id});else if(e.recurring&&e.date.slice(0,7)<month){const last=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();items.push({...e,date:month+'-'+String(Math.min(last,Number(e.date.slice(8)))).padStart(2,'0'),eventId:e.id});}});state.transactions.filter(t=>t.status==='planned'&&monthOf(t.date)===month).forEach(t=>{if(t.scope==='shared'||state.profile['details'+t.scope.slice(1)])items.push({name:t.description||types[t.type],date:t.date,scope:t.scope,amount:t.amount,txId:t.id});});state.goals.filter(g=>monthOf(g.deadline)===month&&(g.scope==='shared'||state.profile['details'+g.scope.slice(1)])).forEach(g=>items.push({name:'Objectif : '+g.name,date:g.deadline,scope:g.scope,amount:g.target,goal:true}));return items;}
function upcoming(){const a=calendarItems().filter(e=>month!==monthOf(today())||e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);return a.length?a.map(e=>`<div class="goal-row between"><div class="flex"><span class="goal-icon">${icon('calendar',17)}</span><div><h3>${esc(e.name)}</h3><span class="caption">${esc(dateLabel(e.date))} · ${esc(scopeName(e.scope))}</span></div></div><span class="caption">${e.amount?money(e.amount):'Rendez-vous'}</span></div>`).join(''):empty('Un calendrier à votre rythme','Ajoutez vos factures, échéances et rendez-vous budget.','add-event','Ajouter une date','calendar');}
function calendarPage(){const first=new Date(month+'-01T12:00:00'),offset=(first.getDay()+6)%7,days=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),items=calendarItems();return `${heading('Notre Calendrier Financier','Les bonnes dates, pour anticiper ensemble.',`${monthPicker()}${btn('Ajouter une date','add-event','plus','primary')}`)}<div class="notice">Les rappels sont visibles dans ce calendrier. Aucune notification n’est envoyée lorsque l’application est fermée. Les dates récurrentes du calendrier ne créent pas de transaction ; utilisez « Échéances du mois » dans les mouvements.</div><div class="legend" style="margin-bottom:20px"><span><i></i>Commun</span><span><i style="background:#8b5cf6"></i>${esc(name('p1'))}</span><span><i style="background:#5278d5"></i>${esc(name('p2'))}</span></div><div class="calendar-grid">${['Lun.','Mar.','Mer.','Jeu.','Ven.','Sam.','Dim.'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>{const day=i-offset+1;if(day<1||day>days)return '<div class="day other"></div>';const d=month+'-'+String(day).padStart(2,'0');return `<div class="day ${d===today()?'today':''}"><div class="day-num">${day}</div>${items.filter(e=>e.date===d).map(e=>`<button class="cal-event ${e.scope}" data-action="${e.txId?'edit-transaction':e.eventId?'edit-event':'open-projects'}" data-id="${esc(e.txId||e.eventId||'')}" title="${esc(e.name)}${e.amount?' · '+money(e.amount):''}">${esc(e.name)}</button>`).join('')}</div>`;}).join('')}</div><section class="card" style="margin-top:22px"><h2>Les rendez-vous du mois</h2>${items.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Événement</th><th>Espace</th><th>Montant prévu</th><th></th></tr></thead><tbody>${items.sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<tr><td>${esc(dateLabel(e.date))}</td><td>${esc(e.name)}${e.recurring?' <span class="badge">Mensuel</span>':''}</td><td>${esc(scopeName(e.scope))}</td><td>${money(e.amount)}</td><td>${e.eventId?`<button class="icon-btn" data-action="edit-event" data-id="${esc(e.eventId)}" aria-label="Modifier">${icon('edit',14)}</button><button class="icon-btn" data-action="delete-event" data-id="${esc(e.eventId)}" aria-label="Supprimer">${icon('trash',14)}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucune date pour ce mois','Ajoutez une échéance pour mieux anticiper.','add-event','Ajouter une date','calendar')}</section>`;}
function simulatorPage(){const basis=incomeBasis(state,month),v=metrics(state,month);return `${heading('Simulateur de Nos Projets','Et si nous explorions nos possibilités ?',monthPicker())}<div class="notice">Simulation indépendante : aucune donnée réelle n’est modifiée. Les calculs supposent des revenus, dépenses et versements constants, sans rendement ni inflation. Les résultats ne garantissent pas une situation future.</div><div class="grid cols2"><section class="card"><h2>Imaginons notre prochain pas</h2><form id="sim-form"><div class="grid cols2" style="margin-top:22px">${field(`Revenus de ${esc(name('p1'))} (${unit()})`,input('a',basis[0]||state.profile.salary1||0,'number','min="0" max="1000000000000" step="any"'))}${field(`Revenus de ${esc(name('p2'))} (${unit()})`,input('b',basis[1]||state.profile.salary2||0,'number','min="0" max="1000000000000" step="any"'))}${field('Charges communes mensuelles',input('shared',v.shared+sum(v.paid.filter(t=>t.type==='principal'&&t.scope==='shared')),'number','min="0" max="1000000000000" step="any"'))}${field('Charges personnelles et capital',input('personal',state.profile.share1&&state.profile.share2?v.personal+sum(v.paid.filter(t=>t.type==='principal'&&t.scope!=='shared')):0,'number','min="0" max="1000000000000" step="any"'))}${field('Épargne mensuelle envisagée',input('saving',state.profile.share1&&state.profile.share2?v.saved||0:v.sharedSaving,'number','min="0" max="1000000000000" step="any"'))}${field('Réduction des charges communes (%)',input('reduction',0,'number','min="0" max="100" step="1"'))}${field('Montant du projet',input('target',0,'number','min="0" max="1000000000000" step="any"'))}${field('Déjà épargné pour ce projet',input('opening',0,'number','min="0" max="1000000000000" step="any"'))}${field(`Part de ${esc(name('p1'))} pour la méthode personnalisée (%)`,input('custom',state.profile.percent,'number','min="0" max="100" step="1"'))}</div></form><div class="flex" style="margin-top:22px;flex-wrap:wrap">${btn('Réduire les charges de 15 %','sim-reduce','','small')}${btn('Perte du revenu 2','sim-loss','','small')}${btn('Augmentation de 10 %','sim-raise','','small')}</div><p class="help" style="margin-top:18px">Les revenus sont préremplis à partir des encaissements, ou à défaut des prévisions du profil. Les parts personnelles masquées ne sont pas préremplies. Les charges essentielles et les dettes sont à inclure dans vos hypothèses.</p></section><div id="sim-results">${simulationHTML({a:basis[0]||state.profile.salary1||0,b:basis[1]||state.profile.salary2||0,shared:v.shared+sum(v.paid.filter(t=>t.type==='principal'&&t.scope==='shared')),personal:state.profile.share1&&state.profile.share2?v.personal+sum(v.paid.filter(t=>t.type==='principal'&&t.scope!=='shared')):0,saving:state.profile.share1&&state.profile.share2?v.saved||0:v.sharedSaving,reduction:0,target:0,opening:0,custom:state.profile.percent})}</div></div>`;}
function simulationHTML(x){const shared=x.shared*(1-x.reduction/100),income=x.a+x.b,available=income-shared-x.personal-x.saving,months=x.saving>0?Math.ceil(Math.max(0,x.target-x.opening)/x.saving):null;return `<section class="sim-output"><div class="eyebrow" style="color:#c7bdff">RÉSULTAT ESTIMÉ</div><h2>Notre marge mensuelle après épargne</h2><div class="big-number">${money(available)}</div><p class="muted" style="font-size:12px">${money(income)} de revenus − ${money(shared+x.personal)} de charges − ${money(x.saving)} d’épargne.</p><div style="border-top:1px solid #ffffff22;margin-top:22px;padding-top:18px"><p style="font-size:12px">${x.target?x.target<=x.opening?'Ce projet est déjà couvert par le montant initial.':months!==null?`Projet finançable en environ <b>${months} mois</b>, soit ${esc(monthLabel(shiftMonth(monthOf(today()),months)))} si la totalité de cette épargne lui est affectée.`:'Définissez un versement mensuel pour estimer une date de réalisation.':'Définissez le montant de votre projet pour estimer sa date de réalisation.'}</p>${available<0?'<p style="margin-top:10px;font-size:12px;color:#ffe0b1">Ces hypothèses dépassent les revenus disponibles : ajustez les charges ou l’épargne.</p>':''}</div></section><section class="card" style="margin-top:20px"><h2>Comparer les contributions</h2><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Méthode</th><th>${esc(name('p1'))}</th><th>${esc(name('p2'))}</th></tr></thead><tbody>${[['Parts égales',.5],['Au prorata',income?x.a/income:.5],['Personnalisée',x.custom/100]].map(([l,r])=>{const a=round(shared*r,state.profile.currency);return `<tr><td>${l}</td><td>${money(a)}</td><td>${money(round(shared-a,state.profile.currency))}</td></tr>`;}).join('')}</tbody></table></div><p class="help" style="margin-top:15px">Comparaison portant uniquement sur les charges communes simulées. À revenus nuls, le prorata utilise 50 / 50. La méthode à retenir dépend de votre accord et de vos responsabilités.</p></section>`;}
function analysisItems(){const v=metrics(state,month),s=settlement(state,month),prev=metrics(state,shiftMonth(month,-1)),budget=budgetTotal(state,month),privacy=state.profile.share1&&state.profile.share2,sharedCats=state.categories.map(c=>[c,sum(v.paid.filter(t=>t.scope==='shared'&&isCharge(t)&&t.category===c))]).sort((a,b)=>b[1]-a[1]),recurring=sum(v.paid.filter(t=>t.scope==='shared'&&isCharge(t)&&t.frequency==='monthly'));return [
 ['Nos ressources',`Vous avez enregistré ${money(v.income)} de revenus encaissés : ${money(v.fixed)} fixes et ${money(v.variable)} variables.`, 'Calcul réel'],
 ['Notre quotidien',privacy?`Les dépenses du foyer sont de ${money(v.expense)}, avec ${money(v.shared)} de dépenses communes et ${money(v.personal)} de dépenses personnelles. Le capital remboursé (${money(v.principal)}) est suivi séparément.`:`Les dépenses communes sont de ${money(v.shared)}. Les montants personnels et consolidés sont masqués.`, 'Calcul réel'],
 ['Notre accord de contribution',s.amount?`Selon les méthodes choisies sur vos charges, un transfert de ${money(s.amount)} de ${name(s.from)} à ${name(s.to)} équilibrerait les paiements confirmés.`:'Les paiements individuels des charges communes sont équilibrés selon votre accord.','Calcul réel'],
 ['Nos principaux postes',sharedCats[0]?.[1]?`${sharedCats[0][0]} est le premier poste de charges communes : ${money(sharedCats[0][1])}. Vous pouvez décider ensemble si ce montant correspond à vos priorités.`:'Aucune charge commune confirmée : ajoutez vos mouvements pour obtenir une analyse de vos postes.','Calcul réel'],
 ['Le respect de notre budget',!privacy?'Le total consommé est masqué selon vos réglages personnels.':budget?`Sur ${money(budget)} de budget de décaissements, ${money(v.expense+v.principal)} ont été utilisés (${pct((v.expense+v.principal)/budget*100)}). ${budget>=v.expense+v.principal?'Il reste '+money(budget-v.expense-v.principal)+'.':'Le dépassement est de '+money(v.expense+v.principal-budget)+'.'}`:'Aucun budget mensuel défini. Fixez des enveloppes adaptées à vos revenus, charges et priorités.','Calcul réel'],
 ['Notre marge après engagements',privacy?`Après dépenses, capital et épargne confirmés, le solde du mois est de ${money(v.available)}. Les charges encore prévues représentent ${money(v.pending)} ; si elles sont payées sans nouveau revenu, la marge serait de ${money(v.available-v.pending)}.`:'Le solde et la marge globale sont masqués selon vos réglages.','Calcul et projection distincts'],
 ['Une piste pour les frais récurrents',recurring?`Vos charges communes marquées mensuelles représentent ${money(recurring)}. Vous pourriez revoir les abonnements peu utilisés. Une réduction hypothétique de 10 % de ces charges libérerait ${money(recurring*.1)} par mois, sous réserve de faisabilité.`:'Marquez vos charges régulières « Mensuel » pour repérer les abonnements et autres engagements à revoir ensemble.','Suggestion · hypothèse'],
 ['Notre évolution',privacy&&prev.expense?`Vos dépenses sont ${v.expense>prev.expense?'en hausse':'en baisse'} de ${pct(Math.abs(v.expense-prev.expense)/prev.expense*100)} par rapport au mois précédent. Vérifiez que les deux mois sont complets avant d’en tirer une conclusion.`:'La comparaison demande deux mois renseignés et le partage des totaux personnels. Une absence de saisie ne signifie pas une absence de dépenses.','Comparaison'],
 ['Prochaine étape à deux',v.income?'Convenez d’un rendez-vous budget court pour vérifier les échéances, les engagements de crédit et un versement d’épargne compatible avec votre marge. Chacun peut exprimer ses priorités sans que son revenu détermine sa place.':'Commencez par vos revenus, vos charges essentielles et vos échéances de dette. Vous pourrez ensuite choisir ensemble un objectif d’épargne réaliste.','Recommandation']];}
function analysisPage(){return `${heading('Analyse de Nos Finances','Des repères concrets, pour décider ensemble.',monthPicker())}<div class="notice">Analyse automatique basée uniquement sur vos saisies. Une période incomplète ne permet pas de conclure sur votre situation réelle. Les suggestions et simulations sont identifiées séparément des calculs.</div><section class="card">${analysisItems().map(([t,d,l],i)=>`<div class="analysis-item"><div class="analysis-num">${String(i+1).padStart(2,'0')}</div><div><div class="flex" style="flex-wrap:wrap"><h3>${t}</h3><span class="badge ${l.includes('Suggestion')||l.includes('Recommandation')?'amber':''}">${l}</span></div><p>${esc(d)}</p></div></div>`).join('')}</section>`;}
function reportsPage(){const v=metrics(state,month),s=settlement(state,month),prev=metrics(state,shiftMonth(month,-1)),year=metrics(state,shiftMonth(month,-12)),b=budgetTotal(state,month),privacy=state.profile.share1&&state.profile.share2,show=n=>privacy?money(n):'Masqué';return `${heading('Notre Bilan Financier Mensuel','Un point de repère à conserver et à préparer ensemble.',`${monthPicker()}${btn('Transactions CSV','export-csv','download')}${btn('Imprimer / PDF','print','download','primary')}`)}<div class="notice no-print">Le bouton PDF ouvre l’impression du navigateur : choisissez « Enregistrer au format PDF ». Les détails personnels masqués ne sont pas exportés en CSV. Le bilan respecte le partage des totaux.</div><article class="card report-only"><div class="report-header"><div class="eyebrow">NOTRE BUDGET À DEUX</div><h1>Notre Bilan Financier Mensuel</h1><p class="subtitle">${esc(monthLabel(month))} · ${esc(name('p1'))} & ${esc(name('p2'))} · ${unit()}</p><p class="help">${isDemo?'Données fictives de démonstration.':'Données déclaratives enregistrées dans ce navigateur.'} Bilan créé le ${esc(fullDate(today()))}.</p></div><div class="report-section"><h3>1. Revenus du couple</h3><div class="table-wrap"><table class="report-table"><tbody><tr><td>${esc(name('p1'))}</td><td class="amount-cell">${money(incomeBasis(state,month)[0])}</td></tr><tr><td>${esc(name('p2'))}</td><td class="amount-cell">${money(incomeBasis(state,month)[1])}</td></tr><tr><td>Total encaissé</td><td class="amount-cell">${money(v.income)}</td></tr></tbody></table></div></div><div class="report-section"><h3>2. Dépenses communes</h3><p class="subtitle">${money(v.shared)} de dépenses payées, hors capital. ${money(sum(v.paid.filter(t=>t.scope==='shared'&&t.type==='principal')))} de capital remboursé séparément.</p></div><div class="report-section"><h3>3. Dépenses personnelles</h3><p class="subtitle">${privacy?money(v.personal):'Totaux personnels masqués selon vos réglages.'} · Dépenses totales du foyer : ${show(v.expense)}.</p></div><div class="report-section"><h3>4. Contributions de chaque partenaire</h3><div class="table-wrap"><table class="report-table"><thead><tr><th>Partenaire</th><th>Attendu</th><th>Payé individuellement</th><th>Couvert par compte commun</th></tr></thead><tbody>${['p1','p2'].map((p,i)=>`<tr><td>${esc(name(p))}</td><td>${money(s.expected[i])}</td><td>${money(s.actual[i])}</td><td>${money(s.commonShare[i])}</td></tr>`).join('')}</tbody></table></div><p class="help">Régularisation restante : ${s.amount?`${money(s.amount)} de ${esc(name(s.from))} vers ${esc(name(s.to))}`:'aucune'}. Les charges prévues non payées sont exclues de ce calcul.</p></div><div class="report-section"><h3>5. Budget prévu et dépenses réelles</h3><p class="subtitle">Budget de décaissements : ${money(b)}. Réalisé, capital inclus : ${show(v.expense+v.principal)}. Restant : ${show(b-v.expense-v.principal)}.</p></div><div class="report-section"><h3>6. Bilan d’épargne et trésorerie</h3><p class="subtitle">Versements communs : ${money(v.sharedSaving)}. Versements personnels : ${show(v.personalSaving)}. Taux d’épargne global : ${privacy?pct(v.rate):'masqué'}. Solde disponible après dépenses, capital et versements : ${show(v.available)}.</p></div><div class="report-section"><h3>7. Évolution des finances</h3><div class="table-wrap"><table class="report-table"><thead><tr><th>Période</th><th>Revenus</th><th>Dépenses</th><th>Versements d’épargne</th></tr></thead><tbody>${[[shiftMonth(month,-12),year],[shiftMonth(month,-1),prev],[month,v]].map(([m,x])=>`<tr><td>${esc(monthLabel(m))}</td><td>${money(x.income)}</td><td>${show(x.expense)}</td><td>${show(x.saved)}</td></tr>`).join('')}</tbody></table></div><p class="help">Les périodes sans données restent à zéro ; elles ne constituent pas des mois validés sans dépenses.</p></div><div class="report-section"><h3>8. Projets et objectifs</h3>${state.goals.filter(g=>g.scope==='shared').length?state.goals.filter(g=>g.scope==='shared').map(g=>{const p=goalProgress(state,g);return `<p class="subtitle">${esc(g.name)} : ${money(p.saved)} / ${money(g.target)} (${pct(p.percent)}), cible ${esc(fullDate(g.deadline))}. Stock actuel, toutes dates confondues.</p>`;}).join(''):'<p class="subtitle">Aucun objectif commun défini.</p>'}</div><div class="report-section"><h3>9. Analyse des risques</h3><p class="subtitle">${privacy?`Charges prévues non confirmées : ${money(v.pending)}. Marge après leur paiement, sans nouveau revenu : ${money(v.available-v.pending)}.`:'La marge globale est masquée.'} Les encours de crédit ne sont pas estimés à partir des seules échéances : vérifiez les soldes dus auprès de vos prêteurs. L’absence de saisie peut sous-estimer les engagements.</p></div><div class="report-section"><h3>10. Recommandations pour le mois suivant</h3><p class="subtitle">${esc(analysisItems()[8][1])}</p><p class="help" style="margin-top:14px">Méthode : seuls les paiements confirmés sont comptabilisés. Les transferts internes et remboursements entre partenaires ne constituent ni revenus ni dépenses du foyer. L’épargne est une affectation de trésorerie, et le capital remboursé est distinct des intérêts et frais.</p></div></article>`;}
function settingsPage(){return `${heading('Paramètres','Vos données, vos préférences et vos sauvegardes.')}<div class="grid cols2"><section class="card"><h2>Données et sauvegardes</h2><div class="setting-row"><div><h3>Sauvegarde complète</h3><p>Un fichier JSON contenant le profil, tous les mouvements, les objectifs et les budgets, y compris les détails personnels masqués. Conservez-le dans un endroit sûr.</p></div>${btn('Exporter','export-json','download')}</div><div class="setting-row"><div><h3>Restaurer une sauvegarde</h3><p>Importez un fichier JSON précédemment exporté. Une étape de validation précède le remplacement des données de ce navigateur.</p></div>${btn('Importer','import-json','upload')}</div><div class="setting-row"><div><h3>Table de transactions</h3><p>CSV compatible Excel, en français, avec la devise. Respecte les filtres et le masquage des détails personnels. Pour importer des données, utilisez le format de sauvegarde JSON.</p></div>${btn('CSV du mois','export-csv','file')}</div><div class="setting-row"><div><h3>Exemples fictifs</h3><p>Explorez un jeu d’exemples indépendant. Vos données réelles restent conservées et ne seront pas écrasées.</p></div>${btn(isDemo?'Quitter':'Explorer',isDemo?'exit-demo':'demo','spark')}</div><div class="setting-row" style="border:0"><div><h3>Effacer cet espace local</h3><p>Supprime toutes les données de ce navigateur. Une confirmation est demandée avant l’effacement.</p></div>${btn('Effacer','reset','trash','danger')}</div></section><div class="stack"><section class="card"><h2>Apparence</h2><div class="setting-row" style="border:0"><div><h3>${state.theme==='dark'?'Thème sombre':'Thème clair'}</h3><p>Un espace confortable sur téléphone et ordinateur.</p></div>${btn('Changer','theme',state.theme==='dark'?'sun':'moon')}</div></section><section class="card"><h2>Nos catégories</h2><p class="subtitle">Ajoutez vos catégories ou renommez-les. Les mouvements et budgets existants seront mis à jour.</p><div class="tag-list" style="margin:18px 0">${state.categories.map(c=>`<span class="tag">${esc(c)}<button class="icon-btn" style="min-width:22px;min-height:22px" data-action="edit-category" data-category="${esc(c)}" aria-label="Renommer ${esc(c)}">${icon('edit',11)}</button></span>`).join('')}</div>${btn('Ajouter une catégorie','add-category','plus','small')}</section><section class="card"><h2>Confidentialité et stockage</h2><p class="subtitle">Les données restent dans le stockage de ce navigateur. Elles ne sont pas synchronisées sur un serveur et ne sont pas chiffrées par l’application. La publication privée protège l’accès au site hébergé ; elle ne crée pas deux comptes partenaires.</p><p class="subtitle">Le masquage des détails est une préférence d’affichage, accessible aux utilisateurs de cet appareil. Pour des finances personnelles sensibles, utilisez des sessions de navigateur distinctes. La navigation privée, un nettoyage du navigateur ou un changement d’appareil peuvent supprimer ou rendre vos données inaccessibles.</p><p class="subtitle">Aucun service bancaire n’est connecté. Les rappels restent dans le calendrier. La police d’interface peut être chargée depuis Google Fonts ; aucune donnée financière ne lui est transmise.</p></section></div></div>`;}
const modal=document.querySelector('#modal');
let pendingConfirm=null;
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Fermer">${icon('close',20)}</button></div>${body}`;if(!modal.open)modal.showModal();modal.querySelectorAll('label').forEach((l,i)=>{const el=l.nextElementSibling;if(el?.matches('input,select,textarea')){el.id||=`modal-field-${i}`;l.htmlFor=el.id;}});}
function closeModal(){modal.close();pendingConfirm=null;}
function confirmAction(title,text,callback,label='Confirmer'){pendingConfirm=callback;openModal(title,`<p class="subtitle">${text}</p><div class="form-actions">${btn('Annuler','close-modal')}${btn(label,'confirm','check','primary')}</div>`);}
function transactionModal(existing=null,preset={}){let t={id:'',type:page==='income'?'income':'expense',amount:'',date:month===monthOf(today())?today():month+'-01',scope:page==='personal'?personal:'shared',owner:personal,payer:personal,from:'p1',to:'p2',category:state.categories[0]||'Autres',subcategory:'',description:'',source:'Salaire principal',status:'paid',frequency:'once',split:'default',percent:state.profile.percent,receipt:'',goalId:'',beneficiary:'',...existing,...preset};
const partners={p1:name('p1'),p2:name('p2')},accounts={...partners,common:'Compte commun'};
openModal(existing?'Modifier le mouvement':'Ajouter un mouvement',`<form data-form="transaction" data-id="${esc(t.id)}"><div class="grid cols2">${field('Type de mouvement',select('type',types,t.type,'id="tx-type"'))}${field('Date',input('date',t.date,'date','required min="1900-01-01" max="2200-12-31"'))}${field(`Montant (${unit()})`,input('amount',t.amount,'number',`required min="${['XOF','XAF'].includes(state.profile.currency)?1:.01}" max="1000000000000" step="${['XOF','XAF'].includes(state.profile.currency)?1:.01}" placeholder="0"`))}${field('Statut du paiement',select('status',{paid:'Confirmé · encaissé ou payé',planned:'Prévu · pas encore payé'},t.status))}<div data-tx-group="normal">${field('Espace concerné',select('scope',{shared:'Commun',...partners},t.scope,'id="tx-scope"'))}</div><div data-tx-group="owner">${field('Partenaire concerné',select('owner',partners,t.owner))}</div><div data-tx-group="charge">${field('Payé par',select('payer',accounts,t.payer))}</div><div data-tx-group="charge">${field('Catégorie',select('category',Object.fromEntries(state.categories.map(c=>[c,c])),t.category,'id="tx-category"'))}</div><div data-tx-group="charge">${field('Sous-catégorie (modifiable)',input('subcategory',t.subcategory,'text','list="subcategories" maxlength="100" placeholder="Ex. Loyer, Courses…"'))}<datalist id="subcategories">${Object.values(subcategories).flat().map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist></div><div data-tx-group="income">${field('Source du revenu',select('source',Object.fromEntries(['Salaire principal','Activités secondaires','Freelance','Revenus commerciaux','Primes','Commissions','Revenus passifs','Autres revenus'].map(c=>[c,c])),t.source))}</div><div data-tx-group="saving">${field('Objectif d’épargne',select('goalId',{'':'Sans objectif attribué',...Object.fromEntries(state.goals.filter(g=>g.scope==='shared'||state.profile['details'+g.scope.slice(1)]||g.id===t.goalId).map(g=>[g.id,g.name+' · '+scopeName(g.scope)]))},t.goalId),'L’espace du versement suivra celui de l’objectif sélectionné.')}</div><div data-tx-group="transfer">${field('Compte de départ',select('from',accounts,t.from))}</div><div data-tx-group="transfer">${field('Compte de destination',select('to',accounts,t.to))}</div>${field('Fréquence',select('frequency',frequency,t.frequency))}<div data-tx-group="charge">${field('Mode de répartition',select('split',{default:'Accord du couple',...methods},t.split))}</div><div data-tx-group="charge">${field(`Part de ${esc(name('p1'))} (%)`,input('percent',t.percent,'number','min="0" max="100" step="0.1"'),'Uniquement pour la méthode personnalisée et les charges communes.')}</div><div data-tx-group="charge">${field('Bénéficiaire (facultatif)',input('beneficiary',t.beneficiary,'text','maxlength="100" placeholder="Une personne ou le foyer"'))}</div></div><div style="margin-top:16px">${field('Description (facultative)',input('description',t.description,'text','maxlength="300" placeholder="À quoi correspond ce mouvement ?"'))}</div><div data-tx-group="charge" style="margin-top:16px">${field('Référence du justificatif (facultative)',input('receipt',t.receipt,'text','maxlength="300" placeholder="Référence de facture ou emplacement du fichier"'),'L’application conserve une référence textuelle ; aucun fichier n’est téléversé.')}</div><p class="help" id="tx-help" style="margin-top:16px"></p><div class="form-actions">${btn('Annuler','close-modal')}<button type="submit" class="btn primary">${icon('check',15)} Enregistrer</button></div></form>`);updateTxGroups();}
function updateTxGroups(){const type=modal.querySelector('[name="type"]')?.value;if(!type)return;const charge=['expense','interest','principal'].includes(type),transfer=['transfer','reimbursement'].includes(type);modal.querySelectorAll('[data-tx-group]').forEach(el=>{const group=el.dataset.txGroup,show=group==='normal'?!transfer:group==='owner'?['income','saving'].includes(type):group==='charge'?charge:group==='income'?type==='income':group==='saving'?type==='saving':transfer;el.classList.toggle('hide',!show);});const h=modal.querySelector('#tx-help');h.textContent=transfer?'Un mouvement interne ne change pas les revenus ou dépenses du foyer. Les remboursements servent exclusivement à régulariser les charges communes entre les deux partenaires.':type==='saving'?'Ce versement diminue le solde disponible et augmente l’épargne de l’objectif. Il ne constitue pas une dépense.':type==='principal'?'Le capital remboursé est une sortie de trésorerie distincte des intérêts et des dépenses de consommation.':type==='income'?'Seuls les revenus confirmés sont comptabilisés dans les encaissements.':'Seuls les paiements confirmés réduisent le solde disponible. Les montants prévus figurent dans le calendrier.';}
function goalModal(g=null){const x=g||{id:'',name:'',scope:savingScope,target:'',opening:0,deadline:shiftMonth(month,12)+'-01',priority:'medium',monthly:'',split:'proportional',percent:50};openModal(g?'Modifier l’objectif':'Un nouveau projet à construire',`<form data-form="goal" data-id="${esc(x.id)}"><div class="grid cols2">${field('Nom de l’objectif',input('name',x.name,'text','required maxlength="120" placeholder="Ex. Notre fonds de sécurité"'))}${field('Espace',select('scope',{shared:'Notre épargne commune',p1:name('p1'),p2:name('p2')},x.scope))}${field(`Montant cible (${unit()})`,input('target',x.target,'number','required min="1" max="1000000000000" step="any"'))}${field('Solde initial déjà épargné',input('opening',x.opening,'number','required min="0" max="1000000000000" step="any"'),'Hors versements déjà enregistrés dans l’application.')}${field('Date cible',input('deadline',x.deadline,'date','required min="1900-01-01" max="2200-12-31"'))}${field('Priorité',select('priority',{high:'Haute',medium:'Moyenne',low:'Basse'},x.priority))}${field('Contribution mensuelle prévue',input('monthly',x.monthly,'number','required min="0" max="1000000000000" step="any"'))}${field('Répartition des versements communs',select('split',methods,x.split),'Indépendante de l’accord sur les dépenses.')}${field(`Part personnalisée de ${esc(name('p1'))} (%)`,input('percent',x.percent,'number','min="0" max="100" step="0.1"'))}</div><p class="help" style="margin-top:18px">Exemples d’objectifs : fonds d’urgence, maison, terrain, voiture, mariage, voyage, entreprise, arrivée d’un enfant, investissement ou projet familial.</p><div class="form-actions">${btn('Annuler','close-modal')}<button class="btn primary" type="submit">Enregistrer l’objectif</button></div></form>`);}
function eventModal(e=null){const x=e||{id:'',name:'',date:month+'-01',scope:'shared',amount:0,recurring:false};openModal(e?'Modifier la date':'Une date à retenir',`<form data-form="event" data-id="${esc(x.id)}"><div class="grid cols2">${field('Intitulé',input('name',x.name,'text','required maxlength="150" placeholder="Ex. Loyer, facture, salaire…"'))}${field('Date',input('date',x.date,'date','required min="1900-01-01" max="2200-12-31"'))}${field('Espace',select('scope',{shared:'Commun',p1:name('p1'),p2:name('p2')},x.scope))}${field('Montant prévu (facultatif)',input('amount',x.amount,'number','min="0" max="1000000000000" step="any"'))}</div><label class="checkbox-row"><input type="checkbox" name="recurring" ${x.recurring?'checked':''}>Répéter chaque mois à cette date</label><p class="help">Rappel visuel uniquement : aucun paiement ou revenu ne sera créé automatiquement.</p><div class="form-actions">${btn('Annuler','close-modal')}<button class="btn primary" type="submit">Enregistrer la date</button></div></form>`);}
function categoryModal(old=''){openModal(old?'Renommer la catégorie':'Ajouter une catégorie',`<form data-form="category" data-old="${esc(old)}">${field('Nom de la catégorie',input('category',old,'text','required maxlength="80"'))}<div class="form-actions">${btn('Annuler','close-modal')}<button class="btn primary" type="submit">Enregistrer</button></div></form>`);}
function download(content,filename,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvExport(){let ts=['income','shared','personal'].includes(page)?filteredTransactions():metrics(state,month).chosen;ts=visibleTransactions(ts).filter(t=>(!filters.partner||t.owner===filters.partner||t.payer===filters.partner)&&(!filters.category||t.category===filters.category)&&(!filters.type||t.type===filters.type)&&(!filters.status||t.status===filters.status));const columns=['Date','Type','Espace','Partenaire concerné','Payé par','Source','Catégorie','Sous-catégorie','Description','Montant', 'Devise','Statut','Fréquence','Compte de départ','Compte de destination','Mode de répartition','Part partenaire 1 (%)','Bénéficiaire','Objectif','Justificatif'];const cell=v=>{const text=String(v??'');return '"'+(/^[\s]*[=+@\-]/.test(text)?"'"+text:text).replace(/"/g,'""')+'"';};const rows=ts.map(t=>[t.date,types[t.type],scopeName(t.scope),name(t.owner),accountName(t.payer),t.source,t.category,t.subcategory,t.description,String(t.amount).replace('.',','),state.profile.currency,t.status==='paid'?'Confirmé':'Prévu',frequency[t.frequency],['transfer','reimbursement'].includes(t.type)?accountName(t.from):'', ['transfer','reimbursement'].includes(t.type)?accountName(t.to):'',t.split==='default'?'Accord du couple':methods[t.split],t.percent,t.beneficiary,state.goals.find(g=>g.id===t.goalId)?.name||'',t.receipt]);download('\ufeff'+[columns,...rows].map(r=>r.map(cell).join(';')).join('\r\n'),`notre-budget-${month}${isDemo?'-DEMO':''}.csv`,'text/csv;charset=utf-8');toast(`${ts.length} mouvement(s) exporté(s).`);}
function generateRecurring(){const recurring=state.transactions.filter(t=>t.frequency==='monthly'&&monthOf(t.date)<month),groups=new Map();for(const t of recurring){const id=t.seriesId||t.id;if(!groups.has(id)||groups.get(id).date<t.date)groups.set(id,t);}let count=0;for(const [seriesId,t] of groups){if(state.transactions.some(x=>(x.seriesId||x.id)===seriesId&&monthOf(x.date)===month))continue;const root=state.transactions.find(x=>x.id===seriesId)||t,last=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),date=month+'-'+String(Math.min(last,Number(root.date.slice(8)))).padStart(2,'0');state.transactions.push({...t,id:uid(),seriesId,date,status:'planned'});count++;}save(count?`${count} échéance(s) créée(s) au statut prévu. Confirmez-les après paiement.`:'Aucune nouvelle échéance à créer pour ce mois.');}
function updateSimulation(){const form=document.querySelector('#sim-form');if(!form)return;const f=Object.fromEntries(new FormData(form));for(const k in f)f[k]=Math.max(0,Math.min(k==='reduction'||k==='custom'?100:1e12,Number(f[k])||0));document.querySelector('#sim-results').innerHTML=simulationHTML(f);}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){page=nav.dataset.nav;filters={partner:'',category:'',type:'',search:'',status:''};render();window.scrollTo({top:0});return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){
 case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;
 case 'close-modal':closeModal();break;
 case 'confirm':{const callback=pendingConfirm;closeModal();if(callback)await callback();break;}
 case 'theme':state.theme=state.theme==='light'?'dark':'light';save('');break;
 case 'demo':state=demo();isDemo=true;month=monthOf(today());filters={};page='dashboard';render();break;
 case 'exit-demo':state=loadData();isDemo=false;filters={};render();break;
 case 'prev-month':month=shiftMonth(month,-1);render();break;
 case 'next-month':month=shiftMonth(month,1);render();break;
 case 'clear-filters':filters={partner:'',category:'',type:'',search:'',status:''};render();break;
 case 'category-filter':filters.category=state.categories.includes(b.dataset.category)?b.dataset.category:'';render();break;
 case 'personal-tab':personal=b.dataset.partner;render();break;
 case 'saving-tab':savingScope=b.dataset.partner;render();break;
 case 'show-personal':confirmAction('Afficher les détails personnels',`Ce réglage affichera les informations personnelles de ${esc(name(b.dataset.partner))} à toute personne utilisant cet appareil. Faites-le uniquement avec son accord.`,()=>{state.profile['details'+b.dataset.partner.slice(1)]=true;save();},'Afficher les détails');break;
 case 'add-transaction':transactionModal();break;
 case 'edit-transaction':{const t=state.transactions.find(t=>t.id===id);if(t)transactionModal(t);break;}
 case 'delete-transaction':confirmAction('Supprimer ce mouvement ?', 'Le mouvement sera retiré des calculs et de l’historique.',()=>{state.transactions=state.transactions.filter(t=>t.id!==id);save('Mouvement supprimé.');},'Supprimer');break;
 case 'submit-profile':document.querySelector('#profile-form')?.requestSubmit();break;
 case 'set-split':state.profile.split=b.dataset.method;save('Accord de répartition mis à jour.');break;
 case 'settle':{const s=settlement(state,month);transactionModal(null,{type:'reimbursement',scope:'shared',amount:s.amount,from:s.from,to:s.to,description:'Régularisation des charges de '+monthLabel(month)});break;}
 case 'add-goal':goalModal();break;
 case 'edit-goal':goalModal(state.goals.find(g=>g.id===id));break;
 case 'delete-goal':confirmAction('Supprimer cet objectif ?', 'Les versements déjà enregistrés seront conservés comme épargne sans objectif attribué.',()=>{state.goals=state.goals.filter(g=>g.id!==id);state.transactions.forEach(t=>{if(t.goalId===id)t.goalId='';});save('Objectif supprimé, versements conservés.');},'Supprimer');break;
 case 'goal-deposit':{const g=state.goals.find(g=>g.id===id);if(g)transactionModal(null,{type:'saving',goalId:g.id,scope:g.scope,owner:g.scope==='shared'?'p1':g.scope,description:'Versement · '+g.name});break;}
 case 'goal-history':{const g=state.goals.find(g=>g.id===id);if(g){const p=goalProgress(state,g);openModal('Historique · '+esc(g.name),`<div class="notice">Solde initial : ${money(g.opening)}. Versements : ${money(sum(p.payments))}. Total : ${money(p.saved)}.</div>${transactionTable(p.payments.sort((a,b)=>b.date.localeCompare(a.date)))}`);}break;}
 case 'add-event':eventModal();break;
 case 'edit-event':eventModal(state.events.find(e=>e.id===id));break;
 case 'delete-event':confirmAction('Supprimer cette date ?', 'L’événement et ses éventuelles répétitions seront supprimés du calendrier.',()=>{state.events=state.events.filter(e=>e.id!==id);save();},'Supprimer');break;
 case 'open-projects':page='projects';savingScope='shared';render();break;
 case 'copy-budget':{const prev=state.budgets[shiftMonth(month,-1)];if(!prev){toast('Aucun budget enregistré le mois précédent.');break;}const copy=()=>{state.budgets[month]=JSON.parse(JSON.stringify(prev));save('Budget du mois précédent copié.');};if(state.budgets[month])confirmAction('Remplacer le budget du mois ?', 'Les enveloppes du mois seront remplacées par celles du mois précédent. Les mouvements restent conservés.',copy,'Copier le budget');else copy();break;}
 case 'generate-recurring':generateRecurring();break;
 case 'sim-reduce':document.querySelector('#sim-form [name="reduction"]').value=15;updateSimulation();break;
 case 'sim-loss':document.querySelector('#sim-form [name="b"]').value=0;updateSimulation();break;
 case 'sim-raise':{const el=document.querySelector('#sim-form [name="a"]');el.value=round(Number(el.value)*1.1,state.profile.currency);updateSimulation();break;}
 case 'print':window.print();break;
 case 'export-csv':csvExport();break;
 case 'export-json':confirmAction('Exporter toutes les données', 'Cette sauvegarde comprend les transactions personnelles même masquées à l’écran. Vérifiez l’accord de chaque partenaire et conservez le fichier dans un endroit sûr.',()=>{download(JSON.stringify(state,null,2),`notre-budget-sauvegarde-${today()}${isDemo?'-DEMO':''}.json`,'application/json');toast('Sauvegarde complète exportée.');},'Exporter la sauvegarde');break;
 case 'import-json':document.querySelector('#import-file').click();break;
 case 'add-category':categoryModal();break;
 case 'edit-category':categoryModal(b.dataset.category);break;
 case 'reset':confirmAction('Effacer toutes les données ?', 'Le profil, les mouvements, les budgets, les objectifs et les dates de cet espace seront supprimés. Exportez une sauvegarde si vous souhaitez les conserver.',()=>{state=defaults();page='dashboard';filters={};save('Espace réinitialisé.');},'Tout effacer');break;
 }}catch(err){toast('Une erreur est survenue : '+err.message);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='month-select'&&/^\d{4}-\d{2}$/.test(el.value)){month=el.value;render();}else if(el.id.startsWith('filter-')){filters[el.id.replace('filter-','')]=el.value;render();}else if(el.id==='split-range'){state.profile.percent=Number(el.value);save('Répartition personnalisée enregistrée.');}else if(el.id==='tx-type')updateTxGroups();else if(el.id==='tx-scope'){const scope=el.value;if(scope!=='shared'){modal.querySelector('[name="owner"]').value=scope;modal.querySelector('[name="payer"]').value=scope;}}else if(el.id==='import-file'){const file=el.files[0];el.value='';if(!file)return;if(file.size>10000000){toast('Le fichier dépasse la taille maximale de 10 Mo.');return;}try{const imported=validData(JSON.parse(await file.text()));confirmAction('Restaurer cette sauvegarde ?',`${imported.transactions.length} mouvement(s), ${imported.goals.length} objectif(s). Cette restauration remplacera les données ${isDemo?'de démonstration':'de cet appareil'}. Exportez d’abord vos données si vous souhaitez les conserver.`,()=>{state=imported;page='dashboard';filters={};save('Sauvegarde restaurée.');},'Restaurer');}catch(err){toast(err.message||'Le fichier est illisible.');}}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='transaction-search'){const start=el.selectionStart;filters.search=el.value;render();const n=document.querySelector('#transaction-search');n?.focus();n?.setSelectionRange(start,start);}else if(el.closest('#sim-form'))updateSimulation();else if(['rule-needs','rule-wants','rule-save'].includes(el.id)){const vals=['needs','wants','save'].map(k=>Math.max(0,Number(document.querySelector('#rule-'+k).value)||0)),total=sum(vals,x=>x),income=metrics(state,month).income;document.querySelector('#rule-result').textContent=total!==100?`Les parts totalisent ${pct(total)}. Ajustez-les pour obtenir 100 %.`:`Sur ${money(income)} : ${money(income*vals[0]/100)} pour les besoins, ${money(income*vals[1]/100)} pour les envies et ${money(income*vals[2]/100)} pour l’épargne. Aucun budget n’est remplacé.`;}});
document.addEventListener('submit',e=>{if(e.target.id==='sim-form'){e.preventDefault();return;}const form=e.target;if(!form.dataset.form)return;e.preventDefault();const f=Object.fromEntries(new FormData(form));try{switch(form.dataset.form){
 case 'profile':{const oldCurrency=state.profile.currency,apply=()=>{state.profile={...state.profile,...f,salary1:round(Number(f.salary1)||0,f.currency),salary2:round(Number(f.salary2)||0,f.currency),percent:Number(f.percent),share1:!!f.share1,share2:!!f.share2,details1:!!f.details1,details2:!!f.details2};closeModal();save('Notre profil est enregistré.');};if(oldCurrency!==f.currency&&state.transactions.length)confirmAction('Changer l’unité monétaire ?',`Les montants existants garderont leur valeur numérique et seront affichés en ${esc(f.currency)}. Aucune conversion de change n’est effectuée.`,apply,'Changer la devise');else apply();break;}
 case 'transaction':{const old=state.transactions.find(t=>t.id===form.dataset.id),id=old?.id||uid(),type=f.type,goal=state.goals.find(g=>g.id===f.goalId),amount=round(Number(f.amount),state.profile.currency);if(!(amount>0&&Number.isFinite(amount)))throw Error('Saisissez un montant positif.');if(['transfer','reimbursement'].includes(type)&&f.from===f.to)throw Error('Choisissez deux comptes différents.');if(type==='reimbursement'&&(!['p1','p2'].includes(f.from)||!['p1','p2'].includes(f.to)))throw Error('Un remboursement entre partenaires doit relier leurs comptes personnels.');const scope=type==='income'?f.owner:type==='saving'&&goal?goal.scope:['transfer','reimbursement'].includes(type)?'shared':f.scope;const t={...old,id,type,amount,date:f.date,scope,owner:scope==='p1'||scope==='p2'?scope:f.owner,payer:f.payer,from:f.from,to:f.to,category:['expense','interest','principal'].includes(type)?f.category:'Autres',subcategory:['expense','interest','principal'].includes(type)?f.subcategory.trim():'',description:f.description.trim(),source:type==='income'?f.source:'',status:f.status,frequency:f.frequency,split:f.split,percent:Number(f.percent),receipt:f.receipt.trim(),goalId:type==='saving'?f.goalId:'',beneficiary:f.beneficiary.trim()};if(f.frequency==='monthly')t.seriesId=old?.seriesId||id;else delete t.seriesId;if(old)state.transactions=state.transactions.map(x=>x.id===id?t:x);else state.transactions.push(t);closeModal();save('Mouvement enregistré.');break;}
 case 'goal':{const old=state.goals.find(g=>g.id===form.dataset.id),g={id:old?.id||uid(),name:f.name.trim(),scope:f.scope,target:round(Number(f.target),state.profile.currency),opening:round(Number(f.opening),state.profile.currency),deadline:f.deadline,priority:f.priority,monthly:round(Number(f.monthly),state.profile.currency),split:f.split,percent:Number(f.percent)};if(!g.name)throw Error('Donnez un nom à cet objectif.');if(old&&old.scope!==g.scope&&state.transactions.some(t=>t.goalId===g.id))throw Error('Cet objectif a déjà des versements : conservez son espace ou créez un autre objectif.');if(old)state.goals=state.goals.map(x=>x.id===g.id?g:x);else state.goals.push(g);closeModal();save('Objectif enregistré.');break;}
 case 'event':{const id=form.dataset.id||uid(),x={id,name:f.name.trim(),date:f.date,scope:f.scope,amount:round(Number(f.amount)||0,state.profile.currency),recurring:!!f.recurring};if(!x.name)throw Error('Donnez un intitulé à cette date.');if(form.dataset.id)state.events=state.events.map(e=>e.id===id?x:e);else state.events.push(x);closeModal();save('Date enregistrée.');break;}
 case 'budget':{const categories={};state.categories.forEach(c=>categories[c]=round(Number(f['cat:'+c])||0,state.profile.currency));state.budgets[month]={shared:round(Number(f.shared)||0,state.profile.currency),p1:round(Number(f.p1)||0,state.profile.currency),p2:round(Number(f.p2)||0,state.profile.currency),saving:round(Number(f.saving)||0,state.profile.currency),rollover:!!f.rollover,categories};save('Budget mensuel enregistré.');break;}
 case 'category':{const value=f.category.trim(),old=form.dataset.old;if(!value)throw Error('Saisissez un nom de catégorie.');if(['__proto__','prototype','constructor'].includes(value))throw Error('Ce nom de catégorie est réservé.');if(state.categories.includes(value)&&value!==old)throw Error('Cette catégorie existe déjà.');if(old){state.categories=state.categories.map(c=>c===old?value:c);state.transactions.forEach(t=>{if(t.category===old)t.category=value;});Object.values(state.budgets).forEach(b=>{if(old in b.categories){b.categories[value]=b.categories[old];delete b.categories[old];}});}else{if(state.categories.length>=100)throw Error('La limite est de 100 catégories.');state.categories.push(value);}closeModal();save('Catégorie enregistrée.');break;}
 }}catch(err){toast(err.message);}});
window.addEventListener('storage',e=>{if(e.key===KEY&&!isDemo){if(modal.open){toast('Données modifiées dans un autre onglet. Fermez ce formulaire puis actualisez avant de saisir.');return;}state=loadData();render();toast('Données actualisées depuis un autre onglet.');}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
